// Route starts stay at least 0.4 m from the existing front wall; z=0.30 was inside the unchanged capsule radius.
if(EditorApplication.isPlaying)throw new System.Exception("Edit required");var all=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var mf=all.Select(t=>t.GetComponent<MeshFilter>()).Where(m=>m!=null&&m.sharedMesh!=null&&m.transform.IsChildOf(GameObject.Find("24 ShopWorkflow12 - crafted room test").transform)&&m.GetComponent<Renderer>()!=null&&m.GetComponent<Renderer>().enabled&&m.gameObject.activeInHierarchy).ToArray();var temps=new System.Collections.Generic.List<MeshCollider>();var conflicts=new System.Collections.Generic.List<object>();int samples=0;var player=GameObject.Find("Crooked Mortar Player").GetComponent<CharacterController>();var probeGo=new GameObject("Temporary circulation capsule");var capsule=probeGo.AddComponent<CapsuleCollider>();capsule.height=player.height;capsule.radius=player.radius;capsule.center=player.center;capsule.isTrigger=true;
var routes=new[]{("Entry",new Vector3(3.7f,.24f,-3.5f),new Vector3(3.7f,.24f,3.3f)),("Counter customer",new Vector3(3.0f,.24f,.6f),new Vector3(3.0f,.24f,3.3f)),("Staff counter aisle",new Vector3(.95f,.24f,.6f),new Vector3(.95f,.24f,2.7f)),("Stair connection",new Vector3(-.7f,.24f,3.3f),new Vector3(3.6f,.24f,3.3f)),("Kitchen connection",new Vector3(3.6f,.24f,3.3f),new Vector3(6.2f,.24f,3.3f))};
try{foreach(var m in mf){var g=new GameObject("Temporary visible mesh probe");g.transform.SetPositionAndRotation(m.transform.position,m.transform.rotation);g.transform.localScale=m.transform.lossyScale;var c=g.AddComponent<MeshCollider>();c.sharedMesh=m.sharedMesh;temps.Add(c);}foreach(var route in routes){int steps=Mathf.CeilToInt(Vector3.Distance(route.Item2,route.Item3)/.1f);for(int i=0;i<=steps;i++){var p=Vector3.Lerp(route.Item2,route.Item3,i/(float)steps);samples++;foreach(var mesh in temps)if(Physics.ComputePenetration(capsule,p,Quaternion.identity,mesh,mesh.transform.position,mesh.transform.rotation,out _,out float distance)&&distance>.006f)conflicts.Add(new{route=route.Item1,position=p.ToString(),mesh=mesh.sharedMesh.name,distance});}}}finally{foreach(var c in temps)UnityEngine.Object.DestroyImmediate(c.gameObject);UnityEngine.Object.DestroyImmediate(probeGo);}
var report=new{passed=conflicts.Count==0,method="Dense 0.10m capsule-volume probes against the new visible meshes, using the unchanged CharacterController dimensions. Static geometry clearance, not a live player-input or camera-comfort test.",samples,routes=routes.Select(r=>r.Item1).ToArray(),player.height,player.radius,conflicts};System.IO.File.WriteAllText("ArtSource/Blender/Interiors/CrookedMortar/ShopWorkflow12/ClearanceValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));return report;
